/** t('th', 'key', { n: 3 }); falls back to English (every key exists there: test/weblib.test.js). */
export function t(lang, key, vars) {
  let s = TEXT[lang]?.[key] ?? TEXT.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v));
  return s;
}
export const keysOf = (lang) => Object.keys(TEXT[lang]);
export const errorKeysOf = (lang) => Object.keys(ERRORS).filter((n) => typeof ERRORS[n][lang] === 'string');

