const BY_SELECTOR = Object.fromEntries(Object.keys(ERRORS).map((n) => {
  const sig = n === 'CollectionRefused' ? 'CollectionRefused(uint8)' : n === 'InvalidReceiver' ? 'InvalidReceiver(address)' : n === 'NonexistentToken' ? 'NonexistentToken(uint256)' : n === 'ProceedsTooLow' ? 'ProceedsTooLow(uint256,uint256)' : `${n}()`;
  return [keccak(sig).slice(0, 10), n];
}));

/** An RPC/wallet error as a short readable reason (custom errors decoded). */
export function errorText(lang, e) {
  const data = typeof e?.data === 'string' ? e.data : typeof e?.data?.data === 'string' ? e.data.data : '';
  const name = BY_SELECTOR[data.slice(0, 10).toLowerCase()];
  if (name) return ERRORS[name][lang] ?? ERRORS[name].en;
  const m = /execution reverted:?\s*(.*)$/i.exec(String(e?.message ?? ''));
  const s = String(m ? m[1] || 'reverted' : e?.message ?? e).replace(/[\p{Cc}\p{Cf}]/gu, '').slice(0, 160);
  return s;
}
